import React, { useCallback, useEffect, useRef } from "react";
/**
 * This hook registers an event listener that is triggered when a click happens outside the specified node.
 * It supports both DOM tree and React tree detection, similar to Material-UI's ClickAwayListener.
 * Ensure that this hook is only invoked when the target element is in the dom, else the event listeners will _always_ be registered.
 *
 * Consider using `ClickOutsideContainer` if your target element is not a standalone component
 * @param {function} onClickOutside outside click callback
 * @param {HTMLElement | null} target the target element to check against for outside clicks
 * @param {boolean} disableReactTree if true, only DOM tree is considered (ignores portaled elements)
 * @returns {object} object containing onSyntheticEvent handler for React tree detection
 */
const useClickOutside = (onClickOutside, target, disableReactTree = false) => {
    const isClickOutsideDom = useRef(false);
    const syntheticEventRef = useRef(false);
    const handleClickCapture = useCallback((event) => {
        if (!target?.contains(event.target)) {
            isClickOutsideDom.current = true;
        }
        else {
            isClickOutsideDom.current = false;
        }
    }, [target]);
    const handleClickBubble = useCallback((event) => {
        // Capture the React tree state at bubble time (after synthetic events)
        const isClickOutsideReactTree = !syntheticEventRef.current;
        if (isClickOutsideDom.current &&
            (disableReactTree || isClickOutsideReactTree)) {
            onClickOutside(event);
        }
        syntheticEventRef.current = false;
    }, [onClickOutside, disableReactTree]);
    const onSyntheticEvent = useCallback(() => {
        // Mark that a synthetic event occurred, indicating the click bubbled through React tree
        syntheticEventRef.current = true;
    }, []);
    useEffect(() => {
        document.addEventListener("click", handleClickCapture, true);
        document.addEventListener("click", handleClickBubble);
        return () => {
            document.removeEventListener("click", handleClickCapture, true);
            document.removeEventListener("click", handleClickBubble);
        };
    }, [handleClickBubble, handleClickCapture]);
    return { onSyntheticEvent };
};
export const ClickOutsideContainer = ({ children, onClickOutside, target, disableReactTree = false }) => {
    const { onSyntheticEvent } = useClickOutside(onClickOutside, target, disableReactTree);
    const childrenProps = {
        // onMouseDown and not onClick because of the event used by Mui's Select component
        onMouseDown: (event) => {
            onSyntheticEvent();
            const childrenPropsHandler = children.props.onMouseDown;
            if (childrenPropsHandler) {
                childrenPropsHandler(event);
            }
        },
    };
    return React.cloneElement(children, childrenProps);
};
export default useClickOutside;
